#!/usr/bin/env python3
"""Universal Hom-support Hall and tight-neighborhood determinant necessities.
No chosen map, coefficients, evaluations, or instance rank computations.
"""
from pathlib import Path
from functools import lru_cache
from collections import Counter
import contextlib, io, runpy, json, hashlib
ROOT=Path(__file__).resolve().parent
INPUTS={f: hashlib.sha256((ROOT/f).read_bytes()).hexdigest() for f in []}
# Fixed predecessor artifacts, not regenerated by this verifier.
INPUTS = {'rank-three-quotient-frontier-148.json': '1a8799f45af3142ab321d3e47d00a5911158ce4e771e0677fab61aa6a8c96f50', 'unrestricted-dual-splittings-and-pairs.json': '9aac29c629b7eb7d2e507eb663571221626a435b995809f05ecad627db126fab', 'verify_negative_vertex_scalar.py': 'e81f548a7e0ea4069ea293ca3b86b1110c2fd6c2906e8637d1441b35f6f14af2'}
def read(f):
    b=(ROOT/f).read_bytes(); assert hashlib.sha256(b).hexdigest()==INPUTS[f],f
    return json.loads(b)
assert hashlib.sha256((ROOT/'verify_negative_vertex_scalar.py').read_bytes()).hexdigest()==INPUTS['verify_negative_vertex_scalar.py']
with contextlib.redirect_stdout(io.StringIO()):
    r=runpy.run_path(str(ROOT/'verify_negative_vertex_scalar.py'))
names=('one','W','Wp','A','V','P','S','D','T')
reps={n:r[n] for n in names}; D={n:int(c[0][0]) for n,c in reps.items()}
assert sum(d*d for d in D.values())==120
assert [n for n in names if D[n]==1]==['one']
for i in names:
    for j in names: assert r['inner'](reps[i],reps[j])==r['z'](int(i==j))
# Thus this complete character list has no nontrivial one-dimensional character;
# every irreducible's determinant character is trivial.
@lru_cache(None)
def hom(e,i,f,j):
    if f<e:return False
    n=r['inner'](reps[i],r['vmul'](reps[j],[r['sym'](f-e,x) for x in r['W']]))
    assert n[1]==0 and n[0].denominator==1 and n[0]>=0
    return n[0]>0
@lru_cache(None)
def inv(d):
    if d<0:return False
    n=r['inner'](r['one'],[r['sym'](d,x) for x in r['W']])
    assert n[1]==0 and n[0].denominator==1 and n[0]>=0
    return n[0]>0
def nd(X):return [(-e-2,i) for e,i in X]
def obstruction(X,Y,det=False):
    for mask in range(1,1<<len(X)):
        S=[a for a in range(len(X)) if mask>>a&1]
        N=[b for b,(f,j) in enumerate(Y) if any(hom(*X[a],f,j) for a in S)]
        a=sum(D[X[i][1]] for i in S);b=sum(D[Y[i][1]] for i in N)
        witness=dict(source_indices=S,target_indices=N,source_rank=a,target_rank=b)
        if a>b:return dict(kind='weighted_Hall',**witness)
        if det and a==b:
            d=sum(Y[i][0]*D[Y[i][1]] for i in N)-sum(X[i][0]*D[X[i][1]] for i in S)
            if not inv(d):return dict(kind='tight_Hall_determinant',determinant_degree=d,**witness)
    return None
base=read('rank-three-quotient-frontier-148.json')
dual=read('unrestricted-dual-splittings-and-pairs.json')
assert base['not_excluded']==148
rows=[];Q_records=[];counts=Counter();direct_ids=[]
for c in base['cases']:
    row=dict(c)
    if c['status']=='not_excluded':
        A,B=c['A'],c['B']; failures=[]
        for direction,X,Y in [('A_to_B_dual_minus2',A,nd(B)),('B_to_A_dual_minus2',B,nd(A))]:
            o=obstruction(X,Y,True)
            if o:failures.append(dict(direction=direction,**o))
        if failures: direct_ids.append(c['id'])
        if c['profile'] in ('11','12'):
            key={'11':'one_one','12':'one_two'}[c['profile']]
            p=next(p for p in dual['compatibility'][key] if p['pair_id']==c['source_index'])
            hall=[];tight=[];removed=[]
            for q in p['Q_ids']:
                Q=dual['profiles'][q]
                h=obstruction(A,nd(Q)) or obstruction(nd(B),nd(Q))
                t=obstruction(A,nd(Q),True) or obstruction(nd(B),nd(Q),True)
                if not h:hall.append(q)
                if not t:tight.append(q)
                else:removed.append(dict(Q_id=q,obstruction=t))
            counts['original_Q_edges']+=len(p['Q_ids']); counts['Hall_Q_edges']+=len(hall);counts['tight_Q_edges']+=len(tight)
            Q_records.append(dict(id=c['id'],input_Q_ids=p['Q_ids'],Hall_Q_ids=hall,tight_Q_ids=tight,removed=removed))
            if not tight:
                counts['empty_Q_cases']+=1
                assert failures, 'New empty common witness: update theorem counts.'
        if failures:
            row.update(status='excluded',reason='weighted equivariant Hom-support Hall obstruction',support_obstructions=failures)
    rows.append(row)
assert set(direct_ids)=={'G3.11.ef6c4c677f42','G3.11.63299e2ae6ab','G3.11.581de282a9e9','G3.11.6cb986f38b24'}
assert dict(counts)==dict(original_Q_edges=2734,Hall_Q_edges=2392,tight_Q_edges=2284,empty_Q_cases=1)
surv=[c for c in rows if c['status']=='not_excluded']
assert len(surv)==144
assert Counter(c['profile'] for c in surv)=={'11':122,'12':10,'21':12}
assert Counter(c['original_defect'] for c in surv)=={0:80,12:50,20:2,24:12}
assert len(rows)==182 and len({c['id'] for c in rows})==182
out=dict(scope=base['scope'],source_hashes=INPUTS,baseline_total=182,previous_remaining=148,newly_excluded=4,excluded=38,not_excluded=144,remaining_by_profile={'11':122,'12':10,'21':12},realizations_claimed=False,global_proof_completion_fraction=None,cases=rows,dual_support_counts=dict(counts),dual_support_records=Q_records)
(ROOT/'rank-three-quotient-frontier-144.json').write_text(json.dumps(out,indent=2)+'\n')
print('PASS: support Hall excludes 4/148; fixed182 now has38 excluded and144 not excluded (122+10+12).')
print('PASS: original defect distribution80/50/2/12 for0/12/20/24; stable IDs retained.')
print('PASS: same-Q witness edges2734 ->2392 (Hall) ->2284 (tight determinant); no further pair exclusion.')
print('Only necessary universal representation/integer constraints; no actual map instances or full-rank assertions.')
